"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { rotateApiKey } from "./api-client";
import { organizationApiKeysKeys } from "./query";

/**
 * Hook for rotating an API key via the v3 API.
 *
 * Invalidates the affected api-key detail key so the next read picks up the updated state.
 */
export const useRotateApiKey = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ apiKeyId }: { apiKeyId: string }) => rotateApiKey({ apiKeyId }),
    onMutate: async ({ apiKeyId }) => {
      // Cancel outgoing refetches to avoid overwriting the optimistic update
      await queryClient.cancelQueries({ queryKey: organizationApiKeysKeys.detail(apiKeyId) });
      const previous = queryClient.getQueryData(organizationApiKeysKeys.detail(apiKeyId));
      // Optimistically clear the key so the UI shows "secret" immediately
      queryClient.setQueryData(organizationApiKeysKeys.detail(apiKeyId), (old: unknown) =>
        old ? { ...old, actualKey: undefined } : old
      );
      return { previous };
    },
    onError: (_err, _vars, context) => {
      // Restore the previous data on error
      if (context?.previous) {
        queryClient.setQueryData(organizationApiKeysKeys.detail(_vars.apiKeyId), context.previous);
      }
    },
    onSettled: (data, error, { apiKeyId }) => {
      // Invalidate the detail key so the next read fetches fresh data
      queryClient.invalidateQueries({ queryKey: organizationApiKeysKeys.detail(apiKeyId) });
      // Also invalidate the list so the table refreshes
      queryClient.invalidateQueries({ queryKey: organizationApiKeysKeys.lists() });
    },
  });
};

/** Typed query-key factory for the api-keys resource. Never inline string keys. */
export const organizationApiKeysKeys = {
  all: ["organization-api-keys"] as const,
  lists: () => [...organizationApiKeysKeys.all] as const,
  list: (organizationId: string) => [...organizationApiKeysKeys.lists(), organizationId] as const,
  details: () => [...organizationApiKeysKeys.all, "detail"] as const,
  detail: (apiKeyId: string) => [...organizationApiKeysKeys.details(), apiKeyId] as const,
  rotate: (apiKeyId: string) => [...organizationApiKeysKeys.details(), "rotate", apiKeyId] as const,
} as const;

/**
 * POST /api/v3/api-keys/{apiKeyId}/rotate — rotate an API key.
 *
 * Generates a new secret, hashes it, clears `lastUsedAt`, and returns the new plaintext key
 * (only ever returned once). Session cookie or x-api-key; the caller must have `apiKey.manage`
 * on the key being rotated.
 */
import { ZId } from "@formbricks/types/common";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { successResponse } from "@/app/api/v3/lib/response";
import { rotateApiKeyService } from "./lib/operations";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "updated",
  targetType: "apiKey",
  schemas: { params: ZId },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) => {
    const result = await rotateApiKeyService({
      apiKeyId: parsedInput.params.apiKeyId,
      authentication,
      auditLog,
      requestId,
      instance,
    });
    return successResponse(result, { requestId });
  },
});

import "server-only";
import { assertCan } from "@/lib/authorization";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";
import type { TV3Authentication, TV3AuditLog } from "@/app/api/v3/lib/types";

export type TRotateApiKeyParams = {
  apiKeyId: string;
  authentication: TV3Authentication;
  auditLog?: TV3AuditLog;
};

/**
 * Rotate an API key: validate access, call the service, and return the new plaintext key.
 *
 * This is the v3 operation layer — it owns auth, audit context, and error mapping.
 * The actual rotation logic lives in `@/modules/organization/settings/api-keys/lib/api-key`.
 */
export async function rotateApiKeyService(params: TRotateApiKeyParams): Promise<{ apiKey: string; actualKey: string }> {
  const { apiKeyId, authentication, auditLog } = params;

  // Resolve the organization for audit logging
  const organizationId = await getOrganizationIdFromApiKeyId(apiKeyId);

  // Verify the caller has permission to manage this key
  if (authentication?.type === "session") {
    await assertCan({ type: "user", id: authentication.user.id }, "apiKey.manage", {
      type: "apiKey",
      id: apiKeyId,
    });
  }

  // Set audit logging context
  if (auditLog) {
    auditLog.organizationId = organizationId;
    auditLog.apiKeyId = apiKeyId;
    auditLog.newObject = { apiKeyId };
  }

  // Perform the rotation via the service layer
  const result = await rotateApiKey(apiKeyId, authentication?.type === "session" ? authentication.user.id : "");

  return {
    apiKey: result.apiKey.id,
    actualKey: result.actualKey,
  };
}

